INSERT INTO "home_content" ("id", "hero_eyebrow", "hero_headline", "hero_cta", "hero_image_url", "quote_text", "quote_label", "contact_heading", "contact_intro") VALUES (1, 'MOBILIE PËR ÇDO DHOMË', 'Shtëpia e bukur
INSERT INTO "about_content" ("id", "hero_image_url", "paragraph_1", "paragraph_2", "values_json", "quote_text", "quote_author") VALUES (1, 'https://cb2.scene7.com/is/image/CB2/102226_DiningEvent_dHP?wid=2400&qlt=88&fmt=jpg', 'Bella Casa do të thotë «shtëpi e bukur». Ky është premtimi ynë: mobilie që e bëjnë çdo dhomë një vend ku ndiheni mirë, të zgjedhura për formën, materialin dhe jetëgjatësinë.', 'Në sallonin tonë gjeni mobilie për dhomën e ndenjes, dhomën e gjumit, kuzhinën, dhomën e ngrënies, zyrën dhe oborrin — dhe shumë prej tyre mund t’i porosisni në përmasat dhe ngjyrat që i duhen shtëpisë suaj.', '[{"title":"Cilësi","description":"Materiale të qëndrueshme dhe punim i kontrolluar në çdo detaj."},{"title":"Me porosi","description":"Përmasa, pëlhura dhe ngjyra sipas shtëpisë suaj."},{"title":"Këshillim","description":"Ju ndihmojmë të zgjidhni mobilien që i shkon dhomës dhe buxhetit."}]'::jsonb, 'Mobilia duhet të ndihet sikur ka qenë gjithmonë pjesë e shtëpisë suaj.', 'Ekipi i Bella Casa') ON CONFLICT (id) DO UPDATE SET "hero_image_url" = EXCLUDED."hero_image_url", "paragraph_1" = EXCLUDED."paragraph_1", "paragraph_2" = EXCLUDED."paragraph_2", "values_json" = EXCLUDED."values_json", "quote_text" = EXCLUDED."quote_text", "quote_author" = EXCLUDED."quote_author";
INSERT INTO "categories" ("id", "slug", "name", "tagline", "hero_image_url", "sort_order") VALUES (1, 'living-room', 'Dhoma e Ndenjes', 'Divane, kolltukë dhe tavolina kafeje për momente të bukura së bashku.', 'https://cb2.scene7.com/is/image/CB2/091026_Newness_MTD_D?wid=1275&qlt=88&fmt=jpg', 0) ON CONFLICT (id) DO UPDATE SET "slug" = EXCLUDED."slug", "name" = EXCLUDED."name", "tagline" = EXCLUDED."tagline", "hero_image_url" = EXCLUDED."hero_image_url", "sort_order" = EXCLUDED."sort_order";
